    }

    /** The sheet's figures added to those of all its descendants, each as it stands now. */
    @Transactional(readOnly = true)
    public Consolidated of(String sheetId) {
        return of(sheetId, null);
    }

    /**
     * The sheet's figures added to those of all its descendants (the tree as it is set now), each sheet's
     * as it stood at the end of an as-of date (null: as it stands now), with that date as its today.
     */
    @Transactional(readOnly = true)
    public Consolidated of(String sheetId, LocalDate asOf) {
        List<String> all = new ArrayList<>();
        all.add(sheetId);
        all.addAll(sheets.descendants(sheetId));
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        List<Set<String>> persons = new ArrayList<>();
        Map<String, BigDecimal> grades = new TreeMap<>();
        Map<String, Integer> statuses = new TreeMap<>();
        for (String id : all) {
            Taken taken = asOf == null ? now(id) : asOf(id, asOf);
            Rollups.Rollup rollup = taken.rollup();
            rollup.people().values().forEach(figures -> {
                if (figures.dueTotal() != null) {
                    dueFigures.add(figures.dueTotal());
                }
                overdueFigures.add(figures.overdueTotal());
            });
            rollup.people().keySet().forEach(personId -> {
                Person person = taken.people().get(personId);
                if (person != null) {
                    persons.add(keys(person));
                }
            });
            LocalDate today = taken.sheet() == null ? null : taken.sheet().getToday();
            taken.people().forEach((personId, person) -> {
                Rollups.Figures figures = rollup.people().get(personId);
                if (person.getRetiredFrom() != null || today == null || figures == null) {
                    return;
                }
                BigDecimal figure = figures.dueTotal() == null ? BigDecimal.ZERO.setScale(2) : figures.dueTotal();
                grades.merge(person.gradeOn(today), figure, BigDecimal::add);
            });
            for (Claim claim : taken.claims()) {
                statuses.merge(claim.getStatus().name(), 1, Integer::sum);
            }
        }
        return new Consolidated(distinct(persons), Rollups.trimmed(dueFigures), Rollups.trimmed(overdueFigures),
                grades, statuses);
    }

    /** A person's name and aliases, each as names are compared. */
    private static Set<String> keys(Person person) {
        Set<String> keys = new HashSet<>();
        keys.add(Person.keyOf(person.getName()));
        person.getAliases().forEach(alias -> keys.add(Person.keyOf(alias)));
        return keys;
    }

    /**
     * How many people there are when those whose names or aliases match, as names are compared, are one
     * person (and so on through whoever they match in turn).
     */
    private static int distinct(List<Set<String>> persons) {
        List<Set<String>> groups = new ArrayList<>();
        for (Set<String> person : persons) {
            Set<String> merged = new HashSet<>(person);
            for (Iterator<Set<String>> it = groups.iterator(); it.hasNext();) {
                Set<String> group = it.next();
                if (!Collections.disjoint(group, merged)) {
                    merged.addAll(group);
                    it.remove();
                }
            }
            groups.add(merged);
        }
        return groups.size();
    }

    /** A sheet's figures as it stands now. */
    private Taken now(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        return new Taken(sheet, rollups.take(sheet, dues.live(sheetId), sheetPeople, sheetClaims), sheetPeople,
                sheetClaims);
    }

    /**
     * A sheet's figures as it stood at the end of a date, with that date as its today: before its today,
     * as kept for that date (none when nothing was kept by then); else as it stands.
     */
    private Taken asOf(String sheetId, LocalDate day) {
        Sheet now = sheets.findById(sheetId).orElse(null);
        if (now == null) {
            return now(sheetId);
        }
        if (day.isBefore(now.getToday())) {
            return history.at(sheetId, day)
                    .map(then -> new Taken(then.sheet(),
                            rollups.take(then.sheet(), then.basis(), then.people(), then.claims().values()),
                            then.people(), then.claims().values()))
                    .orElseGet(() -> {
                        Sheet empty = now.asOf(day, List.of(), null);
                        return new Taken(empty, rollups.take(empty, dues.live(sheetId), new LinkedHashMap<>(),
                                List.of()), Map.of(), List.of());
                    });
        }
        Sheet then = now.asOf(day, now.getDated(), now.getPolicyDate());
        Dues.Basis live = dues.live(sheetId);
        Dues.Basis basis = new Dues.Basis(then, live.rates(), history.inherited(sheetId, day), live.corrected());
        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        return new Taken(then, rollups.take(then, basis, sheetPeople, sheetClaims), sheetPeople, sheetClaims);
    }
}
import { Component, computed, effect, inject, input, signal, untracked } from '@angular/core';
import { FigurePipe } from '../../core/locale';
import { ConsolidatedApi, ConsolidatedView } from '../../core/consolidated';
import { GRADES } from '../../core/people';
import { Session } from '../../core/session';

/** The statuses the consolidated figures count claims by, in the order they list them. */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

// The sheet's figures consolidated over it and all its descendants: the number of people, and each
// sheet's due-total and overdue-total, as that sheet shows them (as of the as-of date while one is set),
// added up; per grade the due-totals of the people on it (retired people left out) added up, and per
// status the count of claims in it, over the tree. Re-read on every sheet load
// and whenever the sheet's own figures move.
@Component({
  selector: 'app-consolidated',
  imports: [FigurePipe],
  template: `
    <section aria-label="Consolidated figures">
      <p>Consolidated people <strong data-testid="consolidated-people-count">{{ figures()?.peopleCount }}</strong></p>
      <p>Consolidated due <strong data-testid="consolidated-due-total">{{ (figures()?.dueTotal) | figure }}</strong></p>
      <p>Consolidated overdue <strong data-testid="consolidated-overdue-total">{{ (figures()?.overdueTotal) | figure }}</strong></p>
      <table>
        <caption>Consolidated by grade</caption>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">Due</th>
          </tr>
        </thead>
        <tbody>
          @for (g of grades(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'consolidated-grade-' + g.grade + '-due-total'">{{ g.dueTotal | figure }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>Consolidated by status</caption>
        <thead>
          <tr>
            <th scope="col">Status</th>
            <th scope="col">Claims</th>
          </tr>
        </thead>
        <tbody>
          @for (s of statuses(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'consolidated-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Consolidated {
  private readonly session = inject(Session);
  private readonly api = inject(ConsolidatedApi);

  /** The sheet's own figures as shown: a move in any of them re-reads the consolidated ones. */
  readonly peopleCount = input.required<number>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();

  protected readonly figures = signal<ConsolidatedView | null>(null);
  /** Per grade, its consolidated due-total; empty until the figures are read. */
  protected readonly grades = computed(() => {
    const figures = this.figures();
    return GRADES.map((grade) => ({
      grade,
      dueTotal: figures ? (figures.gradeDueTotals[grade] ?? '0.00') : '',
    }));
  });
  /** Per status, its consolidated count of claims; empty until the figures are read. */
  protected readonly statuses = computed(() => {
    const figures = this.figures();
    return STATUSES.map((status) => ({
      status,
      count: figures ? String(figures.statusCounts[status] ?? 0) : '',
    }));
  });
  /** Counts reads, so only the answer to the latest one is shown. */
  private reads = 0;

  constructor() {
    // Every sheet load clears the figures shown and re-reads them.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.figures.set(null);
        if (sheet) void this.reload(sheet);
      });
    });
    // A move in the sheet's own today, its as-of date or its figures re-reads them.
    effect(() => {
      this.session.today();
      this.session.asOf();
      this.peopleCount();
      this.dueTotal();
      this.overdueTotal();
      untracked(() => {
        const sheet = this.session.sheet();
        if (sheet) void this.reload(sheet);
      });
    });
  }

  private async reload(sheet: string): Promise<void> {
    const read = ++this.reads;
    try {
      const figures = await this.api.get(sheet);
      if (read === this.reads && this.session.sheet() === sheet) this.figures.set(figures);
    } catch {
      // Left as it was: the next load or change reads them again.
    }
  }
}
